#!/usr/bin/env node
/**
 * Atlas Design System — Token Governance Lint
 *
 * Walks packages/ui-web/src/ and app/ for hardcoded colour/spacing values
 * that should reference --atlas-* CSS custom properties instead.
 *
 * Rules:
 *   1. No hex colour literals (#abc, #aabbcc, #aabbccdd)
 *   2. No rgb() / rgba() calls (outside packages/tokens/)
 *   3. No oklch() calls (outside packages/tokens/)
 *   4. No hsl() / hsla() calls (outside packages/tokens/)
 *
 * Allow-list:
 *   - Lines containing "token-lint-disable-next-line" suppress the NEXT line only.
 *   - Files in packages/tokens/ are always skipped.
 *   - Test files (*.test.*) and governance scripts are skipped.
 *   - Storybook / example files are skipped.
 *
 * Usage:
 *   node packages/governance/token-lint.mjs
 *   node packages/governance/token-lint.mjs --fix   (future — not yet implemented)
 *
 * Exit codes:
 *   0  — no violations
 *   1  — violations found
 */

import fs from "fs"
import path from "path"
import { fileURLToPath } from "url"

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const ROOT = path.resolve(__dirname, "../..")

// ─── Config ──────────────────────────────────────────────────────────────────

const SCAN_DIRS = [
  path.join(ROOT, "packages/ui-web/src"),
  path.join(ROOT, "app"),
]

const SKIP_DIRS = new Set([
  "node_modules",
  ".next",
  ".git",
  "packages/tokens",
  "packages/governance",
])

const SKIP_FILE_PATTERNS = [
  /\.test\.[tj]sx?$/,
  /\.spec\.[tj]sx?$/,
  /\.stories\.[tj]sx?$/,
  /vitest\.config/,
]

const SCAN_EXTENSIONS = new Set([".ts", ".tsx", ".css"])

// ─── Rules ───────────────────────────────────────────────────────────────────

const RULES = [
  {
    id: "no-hex-color",
    description: "Hardcoded hex colour — use an --atlas-* token instead",
    // Matches #RGB, #RRGGBB, #RRGGBBAA — but not CSS ID selectors or comments
    pattern: /(?<![/]{2}[^\n]*)(?:^|[\s:,(])(#[0-9a-fA-F]{3,8})\b/,
    // Skip lines that are pure CSS selectors (e.g. #app { )
    skip: (line) => /^#[\w-]+\s*[{,]/.test(line.trim()),
  },
  {
    id: "no-rgb",
    description: "Hardcoded rgb()/rgba() — use an --atlas-* token instead",
    pattern: /\brgba?\s*\(/,
    skip: () => false,
  },
  {
    id: "no-oklch-raw",
    description: "Raw oklch() outside tokens package — use an --atlas-* token instead",
    pattern: /\boklch\s*\(/,
    // Allow oklch(1 0 0) / oklch(0 0 0) — achromatic white/black anchors used
    // legitimately inside color-mix() as neutral mix targets. Any chroma (C > 0)
    // would indicate a hardcoded brand colour that should become a token.
    skip: (line) => /\bcolor-mix\(in\s+oklch,/.test(line) &&
                    /oklch\(\s*[01]\.?\d*\s+0\s+0\s*\)/.test(line),
  },
  {
    id: "no-hsl",
    description: "Hardcoded hsl()/hsla() — use an --atlas-* token instead",
    pattern: /\bhsla?\s*\(/,
    skip: () => false,
  },
]

// ─── Walker ──────────────────────────────────────────────────────────────────

function* walkFiles(dir) {
  if (!fs.existsSync(dir)) return
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const fullPath = path.join(dir, entry.name)
    if (entry.isDirectory()) {
      const rel = path.relative(ROOT, fullPath)
      if ([...SKIP_DIRS].some((d) => rel.startsWith(d) || entry.name === d)) continue
      yield* walkFiles(fullPath)
    } else if (entry.isFile()) {
      const ext = path.extname(entry.name)
      if (!SCAN_EXTENSIONS.has(ext)) continue
      if (SKIP_FILE_PATTERNS.some((p) => p.test(entry.name))) continue
      yield fullPath
    }
  }
}

// ─── Lint ────────────────────────────────────────────────────────────────────

const violations = []

for (const dir of SCAN_DIRS) {
  for (const filePath of walkFiles(dir)) {
    const rel = path.relative(ROOT, filePath)
    const lines = fs.readFileSync(filePath, "utf8").split("\n")

    let suppressNext = false
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i]
      const lineNo = i + 1

      if (line.includes("token-lint-disable-next-line")) {
        suppressNext = true
        continue
      }

      if (suppressNext) {
        suppressNext = false
        continue
      }

      for (const rule of RULES) {
        if (rule.skip(line)) continue
        if (rule.pattern.test(line)) {
          violations.push({ file: rel, line: lineNo, rule: rule.id, text: line.trim() })
        }
      }
    }
  }
}

// ─── Report ──────────────────────────────────────────────────────────────────

if (violations.length === 0) {
  console.log("✅ Token lint: 0 violations")
  process.exit(0)
} else {
  console.error(`❌ Token lint: ${violations.length} violation${violations.length === 1 ? "" : "s"} found\n`)
  let lastFile = null
  for (const v of violations) {
    if (v.file !== lastFile) {
      console.error(`  ${v.file}`)
      lastFile = v.file
    }
    console.error(`    [${v.rule}] line ${v.line}: ${v.text.slice(0, 120)}`)
  }
  console.error(`
To suppress a single line, add a comment on the preceding line:
  /* token-lint-disable-next-line */
`)
  process.exit(1)
}

import Link from "next/link"
import { flows } from "./_shared/flowRegistry"
import { Card, CardHeader, CardTitle, CardDescription, CardContent, CardFooter } from "@atlas/ui-web/compositions/Card/Card"
import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"

export default function PrototypesIndex() {
  return (
    <div
      style={{
        minHeight: "100vh",
        background: "var(--atlas-background)",
        color: "var(--atlas-foreground)",
        fontFamily: "var(--atlas-font-sans)",
      }}
    >
      <div
        style={{
          maxWidth: 880,
          margin: "0 auto",
          padding: "var(--atlas-spacing-12) var(--atlas-spacing-6)",
          display: "flex",
          flexDirection: "column",
          gap: "var(--atlas-spacing-8)",
        }}
      >
        <div>
          <Link
            href="/"
            style={{
              fontSize: "var(--atlas-font-size-sm)",
              color: "var(--atlas-foreground-muted)",
              textDecoration: "none",
            }}
          >
            ← Sandbox
          </Link>
          <h1
            style={{
              margin: "var(--atlas-spacing-3) 0 var(--atlas-spacing-2)",
              fontSize: "var(--atlas-font-size-3xl)",
              fontWeight: 700,
            }}
          >
            Prototype flows
          </h1>
          <p
            style={{
              margin: 0,
              color: "var(--atlas-foreground-muted)",
              fontSize: "var(--atlas-font-size-base)",
              maxWidth: 640,
            }}
          >
            Interactive flows built from Atlas components. Each flow is a small,
            self-contained app under <code>app/prototypes/&lt;slug&gt;</code>.
          </p>
        </div>

        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fill, minmax(280px, 1fr))",
            gap: "var(--atlas-spacing-4)",
          }}
        >
          {flows.map((flow) => (
            <Link
              key={flow.slug}
              href={`/prototypes/${flow.slug}`}
              style={{ textDecoration: "none", color: "inherit" }}
            >
              <Card interactive variant="elevated">
                <CardHeader>
                  <CardTitle>{flow.name}</CardTitle>
                  <CardDescription>{flow.description}</CardDescription>
                </CardHeader>
                <CardContent>
                  <div
                    style={{
                      display: "flex",
                      flexWrap: "wrap",
                      gap: "var(--atlas-spacing-1_5)",
                    }}
                  >
                    {flow.exercises.map((c) => (
                      <Badge key={c} size="sm" variant="secondary">
                        {c}
                      </Badge>
                    ))}
                  </div>
                </CardContent>
                {flow.status && (
                  <CardFooter>
                    <Badge
                      size="sm"
                      variant={
                        flow.status === "stable"
                          ? "success"
                          : flow.status === "experimental"
                          ? "warning"
                          : "info"
                      }
                      dot
                    >
                      {flow.status}
                    </Badge>
                  </CardFooter>
                )}
              </Card>
            </Link>
          ))}
        </div>
      </div>
    </div>
  )
}

"use client"

/**
 * Wise Home Screen Prototype
 * ──────────────────────────────────────────────────────────────
 * Faithful recreation of the Wise mobile banking home screen.
 * Built with Atlas design tokens (spacing, radius, typography, shadow).
 * Brand green (#9fe870) is a Wise-specific override, not an Atlas token.
 *
 * Route: /prototypes/wise-home
 */

import React, { useState } from "react"
import Link from "next/link"

/* ── Wise brand token (local override — NOT an Atlas semantic token) ── */
const WISE_GREEN = "#9fe870"
const WISE_GREEN_DARK = "#7acc4e"
const WISE_BG = "#ffffff"

/* ── Helpers ───────────────────────────────────────────────────── */
function cx(...cls: (string | false | undefined | null)[]): string {
  return cls.filter(Boolean).join(" ")
}

/* ── Inline SVG Icons ─────────────────────────────────────────── */

const IconBarChart = () => (
  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <line x1="18" y1="20" x2="18" y2="10" />
    <line x1="12" y1="20" x2="12" y2="4" />
    <line x1="6" y1="20" x2="6" y2="14" />
  </svg>
)

const IconEye = () => (
  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z" />
    <circle cx="12" cy="12" r="3" />
  </svg>
)

const IconBank = () => (
  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <line x1="3" y1="22" x2="21" y2="22" />
    <line x1="6" y1="18" x2="6" y2="11" />
    <line x1="10" y1="18" x2="10" y2="11" />
    <line x1="14" y1="18" x2="14" y2="11" />
    <line x1="18" y1="18" x2="18" y2="11" />
    <polygon points="12 2 20 7 4 7" />
  </svg>
)

const IconPlus = ({ size = 20 }: { size?: number }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round">
    <line x1="12" y1="5" x2="12" y2="19" />
    <line x1="5" y1="12" x2="19" y2="12" />
  </svg>
)

const IconX = () => (
  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round">
    <line x1="18" y1="6" x2="6" y2="18" />
    <line x1="6" y1="6" x2="18" y2="18" />
  </svg>
)

const IconHome = ({ active }: { active?: boolean }) => (
  <svg width="22" height="22" viewBox="0 0 24 24" fill={active ? WISE_GREEN : "none"} stroke={active ? WISE_GREEN_DARK : "currentColor"} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <path d="M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z" />
    <polyline points="9 22 9 12 15 12 15 22" />
  </svg>
)

const IconCard = () => (
  <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <rect x="1" y="4" width="22" height="16" rx="2" ry="2" />
    <line x1="1" y1="10" x2="23" y2="10" />
  </svg>
)

const IconRecipients = () => (
  <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2" />
    <circle cx="9" cy="7" r="4" />
    <path d="M23 21v-2a4 4 0 0 0-3-3.87" />
    <path d="M16 3.13a4 4 0 0 1 0 7.75" />
  </svg>
)

const IconPayments = () => (
  <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <polyline points="17 1 21 5 17 9" />
    <path d="M3 11V9a4 4 0 0 1 4-4h14" />
    <polyline points="7 23 3 19 7 15" />
    <path d="M21 13v2a4 4 0 0 1-4 4H3" />
  </svg>
)

/* ── Singapore Flag SVG ───────────────────────────────────────── */
const SingaporeFlag = () => (
  <svg width="36" height="36" viewBox="0 0 36 36" style={{ borderRadius: "50%", display: "block" }}>
    <circle cx="18" cy="18" r="18" fill="#fff" />
    <path d="M0 18a18 18 0 0 1 36 0z" fill="#EF3340" />
    {/* Crescent */}
    <circle cx="13" cy="14" r="5" fill="#fff" />
    <circle cx="15" cy="14" r="5" fill="#EF3340" />
    {/* 5 stars */}
    {[0, 1, 2, 3, 4].map((i) => {
      const angle = (i * 72 - 90) * (Math.PI / 180)
      const x = 19 + 3.8 * Math.cos(angle)
      const y = 14 + 3.8 * Math.sin(angle)
      return <polygon key={i} points={star(x, y, 1.2, 0.5, 5)} fill="#fff" />
    })}
  </svg>
)

function star(cx: number, cy: number, outerR: number, innerR: number, points: number): string {
  const pts: string[] = []
  for (let i = 0; i < points * 2; i++) {
    const angle = (i * Math.PI) / points - Math.PI / 2
    const r = i % 2 === 0 ? outerR : innerR
    pts.push(`${cx + r * Math.cos(angle)},${cy + r * Math.sin(angle)}`)
  }
  return pts.join(" ")
}

/* ── Signal/Battery status icons ─────────────────────────────── */
const StatusBarIcons = () => (
  <div style={{ display: "flex", alignItems: "center", gap: 4 }}>
    {/* Signal bars */}
    <svg width="16" height="12" viewBox="0 0 16 12" fill="currentColor">
      <rect x="0" y="8" width="3" height="4" rx="0.5" opacity="0.4" />
      <rect x="4.5" y="5" width="3" height="7" rx="0.5" opacity="0.6" />
      <rect x="9" y="2" width="3" height="10" rx="0.5" />
      <rect x="13.5" y="0" width="2.5" height="12" rx="0.5" />
    </svg>
    {/* Wifi */}
    <svg width="16" height="12" viewBox="0 0 24 18" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round">
      <path d="M1.5 7C5.5 3 18.5 3 22.5 7" opacity="0.5" />
      <path d="M5 11c3.5-3 10.5-3 14 0" opacity="0.7" />
      <path d="M8.5 15c1.5-1.5 6.5-1.5 8 0" />
      <circle cx="12.5" cy="18" r="1" fill="currentColor" stroke="none" />
    </svg>
    {/* Battery */}
    <svg width="24" height="12" viewBox="0 0 24 12" fill="currentColor">
      <rect x="0" y="1" width="20" height="10" rx="2" fill="none" stroke="currentColor" strokeWidth="1.5" />
      <rect x="20.5" y="3.5" width="2.5" height="5" rx="1" />
      <rect x="1.5" y="2.5" width="16" height="7" rx="1" />
    </svg>
  </div>
)

/* ── Main Component ─────────────────────────────────────────── */
export default function WiseHome() {
  const [interestDismissed, setInterestDismissed] = useState(false)

  return (
    <div
      style={{
        minHeight: "100vh",
        background: "var(--atlas-background-muted)",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "flex-start",
        padding: "var(--atlas-spacing-6) var(--atlas-spacing-4)",
        fontFamily: "var(--atlas-font-sans)",
      }}
    >
      {/* Back link */}
      <div style={{ width: "100%", maxWidth: 390, marginBottom: "var(--atlas-spacing-3)" }}>
        <Link
          href="/prototypes"
          style={{
            fontSize: "var(--atlas-font-size-sm)",
            color: "var(--atlas-foreground-muted)",
            textDecoration: "none",
          }}
        >
          ← Prototypes
        </Link>
      </div>

      {/* Phone shell */}
      <div
        style={{
          width: "100%",
          maxWidth: 390,
          minHeight: 844,
          background: WISE_BG,
          borderRadius: "var(--atlas-radius-2xl)",
          boxShadow: "var(--atlas-shadow-xl)",
          overflow: "hidden",
          display: "flex",
          flexDirection: "column",
          position: "relative",
        }}
      >
        {/* ── Status bar ── */}
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            padding: "12px var(--atlas-spacing-4) var(--atlas-spacing-1)",
            fontSize: "var(--atlas-font-size-sm)",
            fontWeight: "var(--atlas-font-weight-semibold)" as React.CSSProperties["fontWeight"],
            color: "var(--atlas-foreground)",
          }}
        >
          <span>9:41</span>
          <StatusBarIcons />
        </div>

        {/* ── Scrollable content ── */}
        <div style={{ flex: 1, overflowY: "auto", paddingBottom: 120 }}>

          {/* ── App header ── */}
          <div
            style={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              padding: "var(--atlas-spacing-3) var(--atlas-spacing-4) var(--atlas-spacing-2)",
            }}
          >
            {/* Avatar */}
            <div style={{ position: "relative", display: "inline-flex" }}>
              <div
                style={{
                  width: 44,
                  height: 44,
                  borderRadius: "var(--atlas-radius-full)",
                  background: "var(--atlas-background-muted)",
                  border: "1.5px solid var(--atlas-border)",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  fontSize: "var(--atlas-font-size-sm)",
                  fontWeight: "var(--atlas-font-weight-bold)" as React.CSSProperties["fontWeight"],
                  color: "var(--atlas-foreground)",
                  letterSpacing: "0.02em",
                }}
                aria-label="User avatar: WY"
              >
                WY
              </div>
              {/* Online dot */}
              <span
                style={{
                  position: "absolute",
                  bottom: 1,
                  right: 1,
                  width: 10,
                  height: 10,
                  background: "#e53935",
                  borderRadius: "var(--atlas-radius-full)",
                  border: "2px solid white",
                }}
              />
            </div>

            {/* Right cluster */}
            <div style={{ display: "flex", alignItems: "center", gap: "var(--atlas-spacing-2)" }}>
              {/* Earn pill */}
              <button
                style={{
                  background: WISE_GREEN,
                  border: "none",
                  borderRadius: "var(--atlas-radius-full)",
                  padding: "var(--atlas-spacing-1_5) var(--atlas-spacing-4)",
                  fontSize: "var(--atlas-font-size-sm)",
                  fontWeight: "var(--atlas-font-weight-semibold)" as React.CSSProperties["fontWeight"],
                  color: "#1a3300",
                  cursor: "pointer",
                  transition: `background var(--atlas-duration-fast) var(--atlas-easing-standard)`,
                }}
                aria-label="Earn SGD 100"
              >
                Earn SGD 100
              </button>

              {/* Eye / hide button */}
              <button
                style={{
                  width: 36,
                  height: 36,
                  borderRadius: "var(--atlas-radius-full)",
                  background: "var(--atlas-background-muted)",
                  border: "none",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  color: "var(--atlas-foreground-muted)",
                  cursor: "pointer",
                }}
                aria-label="Toggle balance visibility"
              >
                <IconEye />
              </button>
            </div>
          </div>

          {/* ── Welcome heading ── */}
          <div
            style={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              padding: "var(--atlas-spacing-2) var(--atlas-spacing-4)",
            }}
          >
            <h1
              style={{
                margin: 0,
                fontSize: 26,
                fontWeight: "var(--atlas-font-weight-bold)" as React.CSSProperties["fontWeight"],
                color: "var(--atlas-foreground)",
                letterSpacing: "var(--atlas-letter-spacing-tight)",
                lineHeight: "var(--atlas-line-height-tight)",
              }}
            >
              Welcome to Wise
            </h1>
            <button
              style={{
                width: 36,
                height: 36,
                borderRadius: "var(--atlas-radius-full)",
                background: "var(--atlas-background-muted)",
                border: "1px solid var(--atlas-border)",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                color: "var(--atlas-foreground-muted)",
                cursor: "pointer",
              }}
              aria-label="View analytics"
            >
              <IconBarChart />
            </button>
          </div>

          {/* ── Action pills ── */}
          <div
            style={{
              display: "flex",
              gap: "var(--atlas-spacing-2)",
              padding: "var(--atlas-spacing-2) var(--atlas-spacing-4) var(--atlas-spacing-4)",
            }}
          >
            {/* Send — filled green */}
            <button
              style={{
                background: WISE_GREEN,
                border: "none",
                borderRadius: "var(--atlas-radius-full)",
                padding: "var(--atlas-spacing-2) var(--atlas-spacing-5)",
                fontSize: "var(--atlas-font-size-base)",
                fontWeight: "var(--atlas-font-weight-semibold)" as React.CSSProperties["fontWeight"],
                color: "#1a3300",
                cursor: "pointer",
                minHeight: "var(--atlas-touch-min)",
                transition: `background var(--atlas-duration-fast) var(--atlas-easing-standard)`,
              }}
            >
              Send
            </button>

            {/* Add money — outlined */}
            {["Add money", "Request"].map((label) => (
              <button
                key={label}
                style={{
                  background: "transparent",
                  border: "1.5px solid var(--atlas-border-strong)",
                  borderRadius: "var(--atlas-radius-full)",
                  padding: "var(--atlas-spacing-2) var(--atlas-spacing-4)",
                  fontSize: "var(--atlas-font-size-base)",
                  fontWeight: "var(--atlas-font-weight-medium)" as React.CSSProperties["fontWeight"],
                  color: "var(--atlas-foreground)",
                  cursor: "pointer",
                  minHeight: "var(--atlas-touch-min)",
                  transition: `border-color var(--atlas-duration-fast) var(--atlas-easing-standard)`,
                }}
              >
                {label}
              </button>
            ))}
          </div>

          {/* ── Balance cards (horizontal scroll) ── */}
          <div
            style={{
              display: "flex",
              gap: "var(--atlas-spacing-3)",
              padding: "0 var(--atlas-spacing-4) var(--atlas-spacing-6)",
              overflowX: "auto",
              scrollbarWidth: "none",
            }}
          >
            {/* SGD balance card */}
