"use client"

/**
 * Profile & Settings Screen Prototype
 * ──────────────────────────────────────────────────────────────
 * Mobile profile + settings screen built entirely from Atlas components
 * and design tokens.
 *
 * Route: /prototypes/settings
 */

import React, { useState } from "react"
import Link from "next/link"
import { PhoneFrame } from "../_shared/PhoneFrame"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Switch } from "@atlas/ui-web/primitives/Switch/Switch"
import {
  Dialog,
  DialogTrigger,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
  DialogClose,
} from "@atlas/ui-web/compositions/Dialog/Dialog"

/* ── Types ─────────────────────────────────────────────────────── */

type Theme = "light" | "dark" | "system"

/* ── Section wrapper ──────────────────────────────────────────── */

function SettingsSection({
  title,
  children,
}: {
  title: string
  children: React.ReactNode
}) {
  return (
    <div style={{ padding: "0 var(--atlas-spacing-4) var(--atlas-spacing-6)" }}>
      <h2
        style={{
          margin: "0 0 var(--atlas-spacing-3)",
          fontSize: "var(--atlas-font-size-sm)",
          fontWeight: "var(--atlas-font-weight-semibold)" as React.CSSProperties["fontWeight"],
          color: "var(--atlas-foreground-muted)",
          textTransform: "uppercase",
          letterSpacing: "var(--atlas-letter-spacing-wide)",
        }}
      >
        {title}
      </h2>
      <div
        style={{
          background: "var(--atlas-background-muted)",
          borderRadius: "var(--atlas-radius-xl)",
          border: "1px solid var(--atlas-border)",
          overflow: "hidden",
        }}
      >
        {children}
      </div>
    </div>
  )
}

function SettingsRow({
  children,
  last = false,
}: {
  children: React.ReactNode
  last?: boolean
}) {
  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        gap: "var(--atlas-spacing-4)",
        padding: "var(--atlas-spacing-4)",
        borderBottom: last ? "none" : "1px solid var(--atlas-border)",
      }}
    >
      {children}
    </div>
  )
}

/* ── Main Component ─────────────────────────────────────────── */

export default function SettingsScreen() {
  const [pushEnabled, setPushEnabled] = useState(true)
  const [emailEnabled, setEmailEnabled] = useState(true)
  const [smsEnabled, setSmsEnabled] = useState(false)
  const [theme, setTheme] = useState<Theme>("system")
  const [signOutOpen, setSignOutOpen] = useState(false)

  const themeOptions: { value: Theme; label: string }[] = [
    { value: "light", label: "Light" },
    { value: "dark", label: "Dark" },
    { value: "system", label: "System" },
  ]

  const userName = "Amina Rahman"
  const userEmail = "amina.rahman@example.com"
  const initials = userName
    .split(" ")
    .map((p) => p[0])
    .join("")
    .slice(0, 2)
    .toUpperCase()

  return (
    <div
      style={{
        minHeight: "100vh",
        background: "var(--atlas-background)",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "flex-start",
        padding: "var(--atlas-spacing-6) var(--atlas-spacing-4)",
        fontFamily: "var(--atlas-font-sans)",
      }}
    >
      {/* Back link */}
      <div style={{ width: "100%", maxWidth: 390, marginBottom: "var(--atlas-spacing-3)" }}>
        <Link
          href="/prototypes"
          style={{
            fontSize: "var(--atlas-font-size-sm)",
            color: "var(--atlas-foreground-muted)",
            textDecoration: "none",
          }}
        >
          ← Prototypes
        </Link>
      </div>

      <PhoneFrame>
        <div style={{ flex: 1, overflowY: "auto", paddingBottom: "var(--atlas-spacing-8)" }}>
          {/* ── Screen title ── */}
          <div style={{ padding: "var(--atlas-spacing-3) var(--atlas-spacing-4) var(--atlas-spacing-2)" }}>
            <h1
              style={{
                margin: 0,
                fontSize: "var(--atlas-font-size-2xl)",
                fontWeight: "var(--atlas-font-weight-bold)" as React.CSSProperties["fontWeight"],
                color: "var(--atlas-foreground)",
                letterSpacing: "var(--atlas-letter-spacing-tight)",
              }}
            >
              Profile & Settings
            </h1>
          </div>

          {/* ── Profile header ── */}
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: "var(--atlas-spacing-4)",
              padding: "var(--atlas-spacing-4)",
              marginBottom: "var(--atlas-spacing-2)",
            }}
          >
            <div
              style={{
                width: 64,
                height: 64,
                borderRadius: "var(--atlas-radius-full)",
                background: "var(--atlas-color-brand-100)",
                color: "var(--atlas-color-brand-700)",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                fontSize: "var(--atlas-font-size-xl)",
                fontWeight: "var(--atlas-font-weight-bold)" as React.CSSProperties["fontWeight"],
                letterSpacing: "0.02em",
                flexShrink: 0,
              }}
              aria-label={`User avatar: ${initials}`}
            >
              {initials}
            </div>
            <div style={{ minWidth: 0 }}>
              <div
                style={{
                  fontSize: "var(--atlas-font-size-lg)",
                  fontWeight: "var(--atlas-font-weight-semibold)" as React.CSSProperties["fontWeight"],
                  color: "var(--atlas-foreground)",
                  overflow: "hidden",
                  textOverflow: "ellipsis",
                  whiteSpace: "nowrap",
                }}
              >
                {userName}
              </div>
              <div
                style={{
                  fontSize: "var(--atlas-font-size-sm)",
                  color: "var(--atlas-foreground-muted)",
                  overflow: "hidden",
                  textOverflow: "ellipsis",
                  whiteSpace: "nowrap",
                }}
              >
                {userEmail}
              </div>
            </div>
          </div>

          {/* ── Notifications ── */}
          <SettingsSection title="Notifications">
            <SettingsRow>
              <Switch
                label="Push notifications"
                description="Get alerts on this device for account activity."
                checked={pushEnabled}
                onCheckedChange={setPushEnabled}
              />
            </SettingsRow>
            <SettingsRow>
              <Switch
                label="Email notifications"
                description="Receive weekly summaries and important updates by email."
                checked={emailEnabled}
                onCheckedChange={setEmailEnabled}
              />
            </SettingsRow>
            <SettingsRow last>
              <Switch
                label="SMS notifications"
                description="Get a text for time-sensitive security alerts."
                checked={smsEnabled}
                onCheckedChange={setSmsEnabled}
              />
            </SettingsRow>
          </SettingsSection>

          {/* ── Appearance ── */}
          <SettingsSection title="Appearance">
            <div style={{ padding: "var(--atlas-spacing-4)" }}>
              <div
                style={{
                  fontSize: "var(--atlas-font-size-base)",
                  fontWeight: "var(--atlas-font-weight-medium)" as React.CSSProperties["fontWeight"],
                  color: "var(--atlas-foreground)",
                  marginBottom: "var(--atlas-spacing-3)",
                }}
              >
                Theme
              </div>
              <div
                role="radiogroup"
                aria-label="Theme"
                style={{
                  display: "flex",
                  background: "var(--atlas-background)",
                  border: "1px solid var(--atlas-border)",
                  borderRadius: "var(--atlas-radius-lg)",
                  padding: "var(--atlas-spacing-1)",
                  gap: "var(--atlas-spacing-1)",
                }}
              >
                {themeOptions.map((opt) => {
                  const selected = theme === opt.value
                  return (
                    <button
                      key={opt.value}
                      type="button"
                      role="radio"
                      aria-checked={selected}
                      onClick={() => setTheme(opt.value)}
                      style={{
                        flex: 1,
                        border: "none",
                        borderRadius: "var(--atlas-radius-md)",
                        padding: "var(--atlas-spacing-2) var(--atlas-spacing-3)",
                        fontSize: "var(--atlas-font-size-sm)",
                        fontWeight: (selected
                          ? "var(--atlas-font-weight-semibold)"
                          : "var(--atlas-font-weight-regular)") as React.CSSProperties["fontWeight"],
                        color: selected
                          ? "var(--atlas-foreground-on-brand)"
                          : "var(--atlas-foreground-muted)",
                        background: selected ? "var(--atlas-color-brand-600)" : "transparent",
                        cursor: "pointer",
                        minHeight: "var(--atlas-touch-min)",
                        transition: `background var(--atlas-duration-fast) var(--atlas-easing-standard), color var(--atlas-duration-fast) var(--atlas-easing-standard)`,
                      }}
                    >
                      {opt.label}
                    </button>
                  )
                })}
              </div>
            </div>
          </SettingsSection>

          {/* ── Sign out ── */}
          <div style={{ padding: "0 var(--atlas-spacing-4)" }}>
            <Dialog open={signOutOpen} onOpenChange={setSignOutOpen}>
              <DialogTrigger asChild>
                <Button variant="destructive" style={{ width: "100%" }}>
                  Sign out
                </Button>
              </DialogTrigger>
              <DialogContent size="sm">
                <DialogHeader>
                  <DialogTitle>Sign out of Atlas?</DialogTitle>
                  <DialogDescription>
                    You&apos;ll need to sign back in to access your account on this device.
                  </DialogDescription>
                </DialogHeader>
                <DialogFooter>
                  <DialogClose asChild>
                    <Button variant="outline">Cancel</Button>
                  </DialogClose>
                  <Button
                    variant="destructive"
                    onClick={() => setSignOutOpen(false)}
                  >
                    Sign out
                  </Button>
                </DialogFooter>
              </DialogContent>
            </Dialog>
          </div>
        </div>
      </PhoneFrame>
    </div>
  )
}

